const PM_BUSINESS_PARTNER: Lesson = {
  slug: "pm-business-partner", module: "PM", track: "אחזקת מפעל · PM", course: "נתוני אב", chapter: "נתוני אב", index: 7,
  title: "שותף עסקי (Business Partner)", level: "בינוני", minutes: 10, trust: "verified-docs", source: "SAP Help Portal — Plant Maintenance (S/4HANA)", lastReviewed: "2026-07-17",
  prev: "pm-work-center",
  next: "pm-equipment",
  blocks: [
    { kind: "objective", trust: "curated", md: "בסוף השיעור תבין מהו מודל ה-Business Partner (BP) האחוד ב-S/4HANA וכיצד הוא מחליף את ההפרדה הישנה בין לקוח (KNA1) לספק (LFA1) ברשומת-אב אחת (BUT000). תדע כיצד שותפים עסקיים משמשים כ'פונקציות שותף' (Partner Functions) על אובייקטים טכניים, הודעות ופקודות אחזקה — למשל תיעוד יצרן, ספק חלפים או קבלן חיצוני — כיצד מוגדר נוהל קביעת שותפים (Partner Determination) דרך OIOM ומשויך בפועל דרך IHPA, ואיזה BAPI_BUPA_* משמש לניהול פרוגרמטי של BP." },
    { kind: "why", trust: "curated", md: "מודל ה-Business Partner הוא ה-single source of truth שמאחד לקוח וספק לישות אחת. באחזקה זה מאפשר לשייך אחריות (Warranty), תפקידים ואנשי קשר לאובייקטים טכניים ולתעד ספקים/יצרנים/קבלנים בהודעות ובפקודות — קריטי לקבלנות משנה (External Services), לתביעות אחריות מול יצרן ולרכש חלפים. ב-S/4HANA ה-BP הוא נקודת הכניסה היחידה (Single Point of Entry): אי-אפשר עוד להקים ספק ב-XK01 או לקוח ב-XD01 — הכל עובר דרך tcode BP עם CVI (Customer-Vendor Integration) שמסנכרן ל-KNA1/LFA1 מאחורי הקלעים. כל קוד Z שנשען ישירות על KNA1/LFA1 בלי BUT000 נשבר במעבר." },
    { kind: "business-value", trust: "curated", md: "BP אחוד מבטל כפילות נתונים בין ספק ללקוח (אותו גורם המשמש גם כספק חלפים וגם כלקוח שירות מתוחזק כפעם אחת), משפר איכות נתוני-אב ומאפשר ממשל נתונים (MDG). באחזקה הוא מאפשר: תיעוד יצרן לצורך תביעת אחריות, שיוך קבלן חיצוני לציוד לצורך קבלנות משנה, ומעקב אחראי לכל אובייקט טכני. התוצאה: פחות רכש כפול, שקיפות מלאה של מי אחראי/מספק כל נכס, ובסיס נקי לתהליכי External Services ו-Warranty Claims." },
    { kind: "where-used", trust: "curated", md: "שותפים עסקיים ופונקציות שותף מופיעים לאורך כל שרשרת ה-PM: על ציוד (Equipment) ומיקום פונקציונלי (Functional Location) בכרטיסיית השותפים; בהודעות אחזקה (IW21/IW22) לתיעוד המדווח/היצרן/הקבלן; בפקודות אחזקה (IW31/IW32) לשיוך ספק לרכיבי חוץ ולתהליך External Services (דרישת רכש→הזמנת רכש לאותו BP); בתביעות אחריות (Warranty) לזיהוי היצרן; וברכש חלפים. נוהל קביעת השותפים מוגדר ב-OIOM ומשויך לפי קטגוריית ציוד/מיקום/סוג הודעה/סוג פקודה." },
    { kind: "key-concepts", trust: "verified-docs", items: ["Business Partner (BUT000) — רשומת-אב אחודה ב-S/4HANA לאנשים/ארגונים: לקוחות, ספקים, יצרנים, קבלנים ואנשי קשר. מחליפה את ההפרדה הישנה KNA1 (לקוח) / LFA1 (ספק).", "BP Roles (תפקידי BP) — אותו שותף יכול לשאת מספר תפקידים בו-זמנית: FLCU00/FLCU01 (לקוח), FLVN00/FLVN01 (ספק), ועוד. התפקיד קובע אילו נתונים (מכירות/רכש) נשמרים.", "CVI — Customer-Vendor Integration: שכבת הסנכרון שמייצרת/מעדכנת אוטומטית את רשומות KNA1/LFA1 ברקע כשמקימים BP. ב-S/4 tcode BP הוא נקודת הכניסה היחידה.", "Partner Function (פונקציית שותף) — התפקיד שהשותף ממלא על אובייקט אחזקה ספציפי: מדווח, אחראי, ספק, יצרן, קבלן. השיוך הפיזי נשמר בטבלת IHPA.", "Partner Determination Procedure (נוהל קביעת שותפים) — מגדיר אילו פונקציות שותף מותרות/חובה לכל קטגוריית אובייקט. מוגדר ומשויך דרך OIOM; נשען על טבלאות TPAR/TPAKO/TPAER.", "BAPI_BUPA_* — משפחת ה-BAPIs לניהול פרוגרמטי של BP: יצירה (BAPI_BUPA_CREATE_FROM_DATA) ושינוי נתונים מרכזיים (BAPI_BUPA_CENTRAL_CHANGE).", "Warranty (אחריות) — ה-BP מזהה את היצרן/הספק לצורך תביעת אחריות על ציוד; קושר בין הנכס הטכני לגורם החיצוני האחראי."] },
    { kind: "cbc-example", trust: "curated", md: "ב-CBC קבלן כיול חיצוני מוקם כ-Business Partner בתפקיד ספק (Vendor role, FLVN00/FLVN01) דרך tcode BP; CVI מסנכרן אוטומטית רשומת LFA1 ברקע. הקבלן משויך כפונקציית שותף 'קבלן' על ציוד המדידה (IE02 → כרטיסיית שותפים → נשמר ב-IHPA). כשנפתחת פקודת אחזקה הכוללת רכיב לא-מלאי (שירות כיול חיצוני), נוצרת דרישת רכש שמתגלגלת להזמנת רכש לאותו BP. במקביל, יצרן המשאבה מתועד כ-BP נוסף בפונקציית שותף 'יצרן' על הציוד — כך שאם המשאבה כושלת בתקופת האחריות, ניתן לזהות מיידית את הגורם לתביעת Warranty." },
    { kind: "flow", trust: "verified-docs", source: "SAP Help Portal — Plant Maintenance (S/4HANA)", lastReviewed: "2026-07-17", steps: ["הקמת BP: tcode BP → בחירת קטגוריה (אדם/ארגון) → הזנת נתונים מרכזיים (שם, כתובת, תקשורת) → נשמר ב-BUT000.", "הוספת תפקיד: הרחבת ה-BP לתפקיד ספק (FLVN00) ו/או לקוח (FLCU00); CVI יוצר/מעדכן אוטומטית את LFA1/KNA1 ברקע.", "הגדרת נוהל קביעת שותפים (OIOM): הגדרת פונקציות השותף המותרות/חובה לכל קטגוריית ציוד/מיקום/סוג הודעה/פקודה (TPAR/TPAKO/TPAER).", "שיוך על אובייקט טכני: IE02 (ציוד) / IL02 (מיקום) → כרטיסיית שותפים → שיוך ה-BP לפונקציית שותף (יצרן/ספק/קבלן) → נשמר ב-IHPA.", "שימוש בתהליך: הודעה (IW22) / פקודה (IW32) יורשות את פונקציות השותף; רכיב חוץ → דרישת רכש → הזמנת רכש לאותו BP.", "אחריות/דיווח: היצרן המתועד ב-BP משמש לתביעת Warranty ולניתוח אחראי-נכס."] },
    { kind: "tables", trust: "verified-docs", source: "SAP Help Portal — Plant Maintenance (S/4HANA)", lastReviewed: "2026-07-17", rows: [{ code: "BUT000", he: "רשומת-האב המרכזית של השותף העסקי (נתונים כלליים: שם, קטגוריה, סוג)" }, { code: "IHPA", he: "שיוך פונקציות שותף בפועל לאובייקטים טכניים/הודעות/פקודות (Plant Maintenance: Partners)" }, { code: "TPAR", he: "הגדרת פונקציות שותף (Partner Functions) — מאגר התפקידים" }, { code: "TPAKO", he: "נהלי קביעת שותפים — כותרת (Partner Determination Procedures)" }, { code: "TPAER", he: "פונקציות שותף המותרות בכל נוהל קביעת שותפים (שורות הנוהל)" }, { code: "BUT020", he: "שיוך כתובות ל-BP (BP addresses)" }, { code: "BUT100", he: "שיוך תפקידי BP (BP roles) לשותף" }] },
    { kind: "tcodes", trust: "verified-docs", source: "SAP Help Portal — Plant Maintenance (S/4HANA)", lastReviewed: "2026-07-17", refs: [{ code: "BP", label: "Maintain Business Partner — נקודת הכניסה היחידה ל-BP ב-S/4HANA", href: "/tcode/BP/" }, { code: "OIOM", label: "שיוך נוהל קביעת שותפים לקטגוריות/סוגים באחזקה" }, { code: "IE02", label: "שינוי ציוד — כולל כרטיסיית שותפים", href: "/tcode/IE02/" }, { code: "IL02", label: "שינוי מיקום פונקציונלי — כולל כרטיסיית שותפים", href: "/tcode/IL02/" }, { code: "IW22", label: "שינוי הודעת אחזקה — שיוך פונקציות שותף", href: "/tcode/IW22/" }, { code: "IW32", label: "שינוי פקודת אחזקה — שיוך שותפים ורכיבי חוץ", href: "/tcode/IW32/" }] },
    { kind: "fiori", trust: "verified-docs", source: "SAP Help Portal — Plant Maintenance (S/4HANA)", lastReviewed: "2026-07-17", refs: [{ code: "Maintain Business Partner" }, { code: "Manage Business Partner Master Data" }, { code: "Manage Technical Objects" }, { code: "Create Maintenance Request" }, { code: "Manage Maintenance Orders" }] },
    { kind: "spro", trust: "verified-docs", source: "SAP Help Portal — Plant Maintenance (S/4HANA)", lastReviewed: "2026-07-17", md: "SPRO → Cross-Application Components → SAP Business Partner → Business Partner → Basic Settings (הגדרת קטגוריות, קבוצות, טווחי מספרים, תפקידי BP). לאינטגרציית לקוח/ספק: Master Data Synchronization → Customer/Vendor Integration (CVI) — הגדרת מיפוי BP↔KNA1/LFA1 ותפקידים. לאחזקה: Plant Maintenance and Customer Service → Master Data in PM and CS → Basic Settings → Partner Determination Procedure — הגדרת פונקציות שותף (TPAR), נהלים (TPAKO/TPAER) ושיוכם דרך OIOM לקטגוריות ציוד/מיקום ולסוגי הודעה/פקודה." },
    { kind: "objects", trust: "verified-docs", source: "SAP Help Portal — Plant Maintenance (S/4HANA)", lastReviewed: "2026-07-17", refs: [{ code: "BAPI_BUPA_CREATE_FROM_DATA", label: "יצירת Business Partner חדש מנתונים (BAPI)" }, { code: "BAPI_BUPA_CENTRAL_CHANGE", label: "שינוי נתונים מרכזיים של BP קיים (BAPI)" }, { code: "BAPI_BUPA_ADDRESS_ADD", label: "הוספת כתובת ל-BP (BAPI)" }, { code: "BAPI_BUPA_ROLE_ADD_2", label: "הוספת תפקיד (BP Role) לשותף עסקי (BAPI)" }, { code: "I_BusinessPartner", label: "CDS View לקריאת נתוני שותף עסקי" }] },
    { kind: "authorizations", trust: "verified-docs", items: ["B_BUPA_RLT", "B_BUPA_GRP", "B_BUPA_ATT", "F_KNA1_*", "I_BEGRP"] },
    { kind: "common-mistakes", trust: "curated", items: ["נוהל קביעת שותפים לא שויך (OIOM) לקטגוריית ציוד/מיקום או לסוג הודעה/פקודה → פונקציות השותף פשוט חסרות באובייקט ואי-אפשר לשייך יצרן/ספק.", "פונקציית שותף שהוגדרה כחובה לא מולאה → חסימה ביצירת הודעה/פקודה (הודעת שגיאה על שותף חסר).", "בלבול בין תפקידי BP (Vendor / Customer / Contact) → נתונים נשמרים בתצוגה שגויה או ה-BP לא נראה ברכש/מכירות.", "הסתמכות על KNA1/LFA1 ישירות בקוד Z במקום על BUT000 → הקוד נשבר ב-S/4 בגלל מודל ה-BP האחוד; יש לקרוא דרך CVI/BUT000.", "ניסיון להקים ספק ב-XK01/לקוח ב-XD01 ב-S/4 → החסימה: הכל חייב לעבור דרך tcode BP עם CVI."] },
    { kind: "troubleshooting", trust: "curated", md: "אם פונקציית שותף לא מופיעה על ציוד/הודעה: ודא ב-OIOM שנוהל קביעת שותפים משויך לקטגוריה/סוג הרלוונטי, ושהפונקציה קיימת בנוהל (TPAKO/TPAER) ומוגדרת ב-TPAR. אם ה-BP לא נראה ברכש: בדוק שהתפקיד ספק (FLVN00/FLVN01) הורחב ושה-CVI סנכרן LFA1 (בדוק בטבלת CVI_VEND_LINK / דרך לוג CVI ב-MDS_LOAD_COCKPIT). אם הקמת BP נכשלת עם שגיאת CVI: בדוק מיפוי הגדרות ה-CVI (מיפוי קבוצות חשבונות ותפקידים) ב-SPRO Master Data Synchronization. שיוך שותף שנשמר אך לא נראה בפקודה: ודא שהפקודה ירשה מההודעה/הציוד ושהתאריך תקף (IHPA מנוהל לפי תוקף)." },
    { kind: "best-practices", trust: "curated", items: ["השתמש ב-tcode BP כנקודת כניסה יחידה לכל הקמת/שינוי לקוח וספק; אל תנסה XK01/XD01 ב-S/4 — הפעל CVI כראוי.", "הגדר את נהלי קביעת השותפים (Partner Determination) פעם אחת בצורה מרכזית ושייך אותם דרך OIOM לכל קטגוריות הציוד/מיקום וסוגי ההודעה/פקודה הרלוונטיים.", "סמן כחובה רק את פונקציות השותף שבאמת נדרשות (כדי לא לחסום יצירת הודעות/פקודות מיותר).", "תעד יצרן וספק כפונקציות שותף על ציוד קריטי מראש — כדי לאפשר תביעות Warranty וקבלנות משנה חלקה.", "בכל קוד Z/CDS חדש קרא נתוני שותף דרך BUT000/I_BusinessPartner, לא ישירות מ-KNA1/LFA1."] },
    { kind: "tips", trust: "curated", items: ["אותו BP יכול לשאת בו-זמנית תפקיד לקוח ותפקיד ספק — נצל זאת לגורם שהוא גם ספק חלפים וגם לקוח שירות, במקום שתי רשומות.", "טבלת IHPA היא המקום לאמת שיוך שותף בפועל לאובייקט; היא מנוהלת לפי תוקף (validity), אז שים לב לתאריכים.", "OIOM היא ה-tcode שמחברת בין הגדרת הנוהל למציאות — אם 'הכל מוגדר אבל כלום לא עובד', בדוק שם קודם.", "T357G היא טבלת Permits (היתרים) ואינה קשורה לקביעת שותפים — טעות נפוצה; קביעת שותפים = OIOM + TPAR/TPAKO/TPAER."] },
    { kind: "notes", title: "הפניות SAP", trust: "verified-docs", source: "SAP Help Portal — Plant Maintenance (S/4HANA)", lastReviewed: "2026-07-17", md: "SAP Help Portal — SAP S/4HANA · Business Partner (BUT000, BP roles, CVI); SAP Help Portal — Plant Maintenance and Customer Service · Partner Determination (IHPA, TPAR/TPAKO/TPAER); ספר PM ch.003 — Warranties; data/pm-master-data-facets.ts — BUT000 (מקור מאומת בפרויקט; תיקון sap-pm-consultant: T357G=Permits, קביעת שותפים=OIOM/TPAR)" },
    { kind: "related", trust: "curated", refs: [{ code: "pm-equipment", label: "ציוד (Equipment) — שיוך פונקציות שותף", href: "/academy/lesson/pm-equipment/" }, { code: "pm-functional-location", label: "מיקום פונקציונלי — שיוך שותפים", href: "/academy/lesson/pm-functional-location/" }, { code: "pm-notification-create", label: "יצירת הודעת אחזקה — פונקציות שותף", href: "/academy/lesson/pm-notification-create/" }, { code: "pm-notification-to-order", label: "מהודעה לפקודה — ירושת שותפים ורכיבי חוץ", href: "/academy/lesson/pm-notification-to-order/" }, { code: "MM-PUR", label: "רכש (Purchasing) — ספק BP לרכיבי חוץ / External Services" }, { code: "QM", label: "ניהול איכות — ספק/יצרן BP בתביעות ובבדיקות" }] },
    { kind: "quiz", trust: "curated", items: [{ question: "מהו השינוי המרכזי במודל השותף העסקי ב-S/4HANA לעומת ECC?", options: [{ text: "KNA1 ו-LFA1 אוחדו לרשומת-אב אחת (BUT000) עם נקודת כניסה יחידה tcode BP, ו-CVI מסנכרן ברקע", correct: true }, { text: "KNA1/LFA1 נמחקו לחלוטין ואין להם שום ייצוג ב-S/4" }, { text: "אין שינוי — עדיין מקימים ספק ב-XK01 ולקוח ב-XD01" }, { text: "השותף העסקי הפך לרלוונטי רק ל-FI ולא לאחזקה" }], explain: "ב-S/4HANA ה-BP הוא ה-single point of entry; KNA1/LFA1 עדיין קיימים ברקע ומסונכרנים אוטומטית דרך CVI, אך התחזוקה עוברת דרך tcode BP בלבד." }, { question: "היכן מוגדר ומשויך נוהל קביעת שותפים (Partner Determination) באחזקה, ואיפה נשמר השיוך בפועל של שותף לאובייקט?", options: [{ text: "הנוהל משויך דרך OIOM (טבלאות TPAR/TPAKO/TPAER), והשיוך בפועל נשמר ב-IHPA", correct: true }, { text: "הכל מוגדר ונשמר ב-T357G (Permits)" }, { text: "הנוהל מוגדר ב-XD01 והשיוך נשמר ב-KNA1" }, { text: "אין הגדרה — פונקציות השותף קבועות ולא ניתנות לשינוי" }], explain: "נוהל קביעת השותפים מוגדר עם TPAR/TPAKO/TPAER ומשויך לקטגוריות/סוגים דרך OIOM; השיוך הפיזי של שותף לאובייקט טכני/הודעה/פקודה נשמר בטבלת IHPA. T357G היא Permits ואינה קשורה." }, { question: "איזה BAPI משמש ליצירת שותף עסקי חדש מנתונים?", options: [{ text: "BAPI_BUPA_CREATE_FROM_DATA", correct: true }, { text: "BAPI_CUSTOMER_CREATEFROMDATA1 בלבד" }, { text: "BAPI_ALM_ORDER_MAINTAIN" }, { text: "BAPI_EQUI_CREATE" }], explain: "משפחת BAPI_BUPA_* מנהלת BP פרוגרמטית: BAPI_BUPA_CREATE_FROM_DATA ליצירה ו-BAPI_BUPA_CENTRAL_CHANGE לשינוי נתונים מרכזיים." }] },
    { kind: "summary", trust: "curated", md: "Business Partner (BUT000) הוא רשומת-האב האחודה של S/4HANA לאנשים וארגונים בתהליכי אחזקה — לקוחות, ספקים, יצרנים, קבלנים ואנשי קשר — ומחליף את ההפרדה הישנה KNA1/LFA1. הכניסה היחידה היא tcode BP, ו-CVI מסנכרן את KNA1/LFA1 ברקע לפי התפקידים (BP Roles). באחזקה משמש ה-BP כ'פונקציית שותף' על ציוד, מיקום, הודעה ופקודה — לתיעוד יצרן (Warranty), ספק חלפים וקבלן חיצוני (External Services). נוהל קביעת השותפים מוגדר עם TPAR/TPAKO/TPAER ומשויך דרך OIOM; השיוך בפועל נשמר ב-IHPA. ניהול פרוגרמטי דרך BAPI_BUPA_*. טעות נפוצה: לשכוח לשייך נוהל ב-OIOM, או להסתמך ישירות על KNA1/LFA1 בקוד Z במקום על BUT000 — מה שנשבר ב-S/4." },
  ],
};

