  slug: "pm-equipment", module: "PM", track: "אחזקת מפעל · PM", course: "אובייקטים טכניים", chapter: "אובייקטים טכניים", index: 8,
  title: "ציוד (Equipment)", level: "בסיסי", minutes: 12, trust: "verified-docs", source: "SAP Help Portal — Plant Maintenance (S/4HANA)", lastReviewed: "2026-07-17",
  prev: "pm-business-partner",
