  slug: "pm-confirmation", module: "PM", track: "אחזקת מפעל · PM", course: "ביצוע אחזקה", chapter: "ביצוע אחזקה", index: 13,
  title: "אישור עבודות", level: "בינוני", minutes: 12, trust: "verified-docs", source: "SAP Help Portal — Plant Maintenance (S/4HANA)", lastReviewed: "2026-07-17",
  prev: "pm-maintenance-order",
