  slug: "pm-maintenance-plan", module: "PM", track: "אחזקת מפעל · PM", course: "אחזקה מונעת", chapter: "אחזקה מונעת", index: 17,
  title: "תכניות אחזקה", level: "בינוני", minutes: 14, trust: "verified-docs", source: "SAP Help Portal — Plant Maintenance (S/4HANA)", lastReviewed: "2026-07-17",
  prev: "pm-settlement",
