  title: "תזמון ומונים", level: "בינוני", minutes: 12, trust: "verified-docs", source: "SAP Help Portal — Plant Maintenance (S/4HANA)", lastReviewed: "2026-07-17",
  prev: "pm-maintenance-plan",
